const now = new Date().toISOString();
const cred = $input.first().json;
return [{
  json: {
    ...cred,
    run_id: `gh-${now.replace(/[^0-9]/g, '').slice(0, 14)}-${Math.random().toString(36).slice(2, 8)}`,
    workflow_name: 'GH Compute — Pain Detector',
    started_at: now,
    finished_at: '',
    status: 'Started',
    sources_requested: 0,
    raw_items: 0,
    new_signals: 0,
    qualified_leads: 0,
    errors: '',
    details: 'Detector run started.'
  }
}];

const now = new Date().toISOString();
let init;
try {
  init = $('Initialize Run').first().json;
} catch (error) {
  init = {
    run_id: `gh-${now.replace(/[^0-9]/g, '').slice(0, 14)}-${Math.random().toString(36).slice(2, 8)}`,
    workflow_name: 'GH Compute — Pain Detector',
    started_at: now
  };
}
let cred;
try {
  cred = $('CREDENCIALS').first().json;
} catch (error) {
  cred = {
    client_name: 'AImetos - Scrap Grasshopper',
    page_name: 'GH Compute Lead Engine',
    google_sheet_id: '1Dd-BimZHX6n8sSTXpdDmVmf0qxNOwMB0cBML0DlbPDw',
    config_sheet_name: '00_CONFIG',
    companies_sheet_name: '01_EMPRESAS_OBJETIVO',
    pain_signals_sheet_name: '02_PAIN_SIGNALS',
    qualified_leads_sheet_name: '03_LEADS_CUALIFICADOS',
    run_log_sheet_name: '04_RUN_LOG',
    outreach_drafts_sheet_name: '05_OUTREACH_DRAFTS',
    timezone: 'Europe/Madrid'
  };
}
const rows = $input.all().map((item) => item.json);

const cfg = {};
for (const row of rows) {
  const key = String(row.key ?? row.Key ?? '').trim();
  if (key) cfg[key] = row.value ?? row.Value ?? '';
}

const errors = [];

const isEnabled = (value) => {
  if (value === true) return true;
  return String(value || '').trim().toLowerCase() === 'true';
};

const parseJson = (key) => {
  try {
    const raw = String(cfg[key] || '').trim();
    if (!raw) throw new Error(`${key} is empty`);
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error(`${key} must be an array`);
    return parsed;
  } catch (error) {
    errors.push(`${key}: ${error.message}`);
    return [];
  }
};

const bool = (value, fallback = false) => {
  if (value === true || value === false) return value;
  const text = String(value ?? '').trim().toLowerCase();
  if (!text) return fallback;
  return text === 'true' || text === '1' || text === 'yes';
};

const cfgText = (key, fallback = '') => {
  const value = cfg[key];
  const text = String(value ?? '').trim();
  return text || fallback;
};

const cfgNumber = (key, fallback, min, max) => {
  const raw = Number(cfg[key]);
  const value = Number.isFinite(raw) ? raw : fallback;
  return Math.max(min, Math.min(max, Math.floor(value)));
};

const renderTemplate = (value, vars) => {
  if (Array.isArray(value)) return value.map((entry) => renderTemplate(entry, vars));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, renderTemplate(entry, vars)]));
  }
  if (typeof value === 'string') {
    return value
      .replaceAll('{{query}}', vars.query || '')
      .replaceAll('{{country}}', vars.country || '')
      .replaceAll('{{countryCode}}', vars.countryCode || '');
  }
  return value;
};

const queries = parseJson('SEARCH_QUERIES_JSON');
const sources = parseJson('APIFY_SOURCES_JSON');

if (!cred.google_sheet_id) errors.push('google_sheet_id is empty in CREDENCIALS');

const openaiModel = cfgText('OPENAI_MODEL', $env.OPENAI_MODEL || 'gpt-4.1-mini');
const defaultOutreachLanguage = cfgText('DEFAULT_OUTREACH_LANGUAGE', 'es');
const defaultApifyTokenEnvVar = cfgText('DEFAULT_APIFY_TOKEN_ENV_VAR', 'APIFY_TOKEN');
const maxItems = cfgNumber('MAX_ITEMS_PER_QUERY', 20, 1, 100);
const maxRawChars = cfgNumber('MAX_RAW_TEXT_CHARACTERS', 6000, 500, 20000);
const pollInterval = cfgNumber('APIFY_POLL_INTERVAL_SECONDS', 20, 5, 300);
const maxPolls = cfgNumber('APIFY_MAX_POLLS', 12, 1, 120);
const minQualifiedScore = cfgNumber('MIN_QUALIFIED_SCORE', 65, 0, 100);
const priorityAScore = cfgNumber('PRIORITY_A_SCORE', 80, 0, 100);

const work = [];

for (const query of queries) {
  for (const source of sources) {
    const endpointUrl = String(source.endpoint_url || '').trim();
    if (!isEnabled(source.enabled)) continue;
    if (!endpointUrl) continue;

    work.push({
      json: {
        ...cred,
        work_item: true,
        run_id: init.run_id,
        workflow_name: init.workflow_name,
        started_at: init.started_at,
        query: String(query.query || ''),
        country: String(query.country || ''),
        countryCode: String(query.countryCode || ''),
        source_id: String(source.id || 'source'),
        source_mode: String(source.mode || 'actor_async_dataset'),
        source_type: String(source.result_type || source.id || 'public_source'),
        endpoint_url: endpointUrl,
        apify_token_env_var: String(source.apify_token_env_var || defaultApifyTokenEnvVar).trim(),
        apify_input: renderTemplate(source.input_template || {}, query),
        openai_model: openaiModel,
        default_outreach_language: defaultOutreachLanguage,
        max_items_per_query: maxItems,
        max_raw_text_characters: maxRawChars,
        poll_interval_seconds: pollInterval,
        max_polls: maxPolls,
        min_qualified_score: minQualifiedScore,
        priority_a_score: priorityAScore,
        summary_email_enabled: bool(cfg.SUMMARY_EMAIL_ENABLED, false),
        summary_email_to: cfgText('SUMMARY_EMAIL_TO', 'hola@aimetos.com'),
        poll_attempt: 0,
        item_errors: errors.slice()
      }
    });
  }
}

if (!work.length) {
  return [{
    json: {
      ...cred,
      ...init,
      work_item: false,
      status: errors.length ? 'Failed' : 'Skipped',
      finished_at: new Date().toISOString(),
      sources_requested: sources.length,
      raw_items: 0,
      new_signals: 0,
      qualified_leads: 0,
      errors: errors.join('; '),
      details: errors.length
        ? 'No valid work items because mandatory configuration is missing or invalid.'
        : 'No enabled Apify source with configured endpoint_url.'
    }
  }];
}

return work;

const context = $('Prepare Apify Request').first().json;
const errors = Array.isArray(context.item_errors) ? context.item_errors.slice() : [];
const inputs = $input.all().map(item => item.json);
let rows = [];
if (inputs.length === 1 && Array.isArray(inputs[0])) rows = inputs[0];
else if (inputs.length === 1 && Array.isArray(inputs[0]?.body)) rows = inputs[0].body;
else if (inputs.length === 1 && Array.isArray(inputs[0]?.data)) rows = inputs[0].data;
else if (inputs.length > 1) rows = inputs;
else if (inputs.length === 1 && inputs[0] && typeof inputs[0] === 'object') {
  const only = inputs[0];
  const looksLikePlace = only.title || only.name || only.url || only.website || only.address;
  if (looksLikePlace) rows = [only];
  else errors.push('Apify did not return a dataset array: ' + JSON.stringify(only).slice(0, 300));
}
if (!rows.length && !errors.length) errors.push('Apify returned 0 places');
return [{ json: { ...context, raw_results: rows, raw_items: rows.length, apify_status: rows.length ? 'SUCCEEDED' : 'EMPTY', run_succeeded: rows.length > 0, item_errors: errors } }];

const stableId = (prefix, value, max = 24) => {
  const text = String(value || '').toLowerCase().trim();
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  const clean = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, max);
  const suffix = (hash >>> 0).toString(36);
  return prefix + '_' + (clean || 'item') + '_' + suffix;
};
const context = $('Attach Start Result').first().json;
const rawItems = Array.isArray(context.raw_results) ? context.raw_results : [];
const cleanText = (value) => String(value ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const normalizeUrl = (value) => {
  try {
    const url = new URL(String(value || '').trim());
    url.hash = '';
    url.search = '';
    return url.toString().replace(/\/$/, '');
  } catch (error) {
    return '';
  }
};
const socialUrl = (value) => /(linkedin\.com|facebook\.com|instagram\.com|x\.com|twitter\.com)/i.test(String(value || ''));
const out = [];
const seen = new Set();
for (const item of rawItems.slice(0, Number(context.max_items_per_query || 20))) {
  if (!item || typeof item !== 'object') continue;
  const title = cleanText(item.title || item.name || item.companyName || item.company_name);
  const company = cleanText(item.company || item.companyName || item.company_name || item.organization || item.title || item.name);
  const sourceUrl = normalizeUrl(item.url || item.link || item.source_url || item.sourceUrl || item.placeUrl || item.googleMapsUrl || item.website);
  const website = !socialUrl(item.website) ? normalizeUrl(item.website) : '';
  const address = cleanText(item.address || item.location || item.street || item.city || item.state);
  const category = cleanText(item.categoryName || item.category || (Array.isArray(item.categories) ? item.categories.join(', ') : ''));
  const text = cleanText([
    title,
    category,
    address,
    item.description,
    item.snippet,
    item.text,
    item.raw_text,
    item.summary,
    item.phone,
    item.phoneUnformatted,
    website
  ].filter(Boolean).join(' ')).slice(0, Number(context.max_raw_text_characters || 6000));
  if (!company || text.length < 10) continue;
  let domain = '';
  try { domain = new URL(website || sourceUrl).hostname.replace(/^www\./, ''); } catch (error) {}
  const dedupeBase = sourceUrl || website || item.placeId || item.cid || [company, address, category].join('|');
  const dedupeKey = stableId('dedupe', dedupeBase, 40);
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  out.push({ json: { run_id: context.run_id, source_id: context.source_id, source_type: context.source_type, company_name: company, website, domain, country: context.country, source_url: sourceUrl || website, source_title: title || company, raw_text: text, raw_item_json: JSON.stringify(item), detected_at: new Date().toISOString(), dedupe_key: dedupeKey, min_qualified_score: context.min_qualified_score, priority_a_score: context.priority_a_score, openai_model: context.openai_model, item_errors: context.item_errors || [] } });
}
if (!out.length) return [{ json: { ...context, run_succeeded: false, item_errors: [...(context.item_errors || []), 'No usable rows found in Apify dataset'] } }];
return out;

const incoming = $('Normalize Results').all().map(item => item.json);
const existing = new Set($input.all().map(item => String(item.json.dedupe_key || '').trim()).filter(Boolean));
return incoming
  .filter(item => item && item.dedupe_key && !existing.has(String(item.dedupe_key).trim()))
  .map(item => ({ json: item }));

