const inputItems = $input.all();
return inputItems.map((inputItem, index) => {
  const source = $('Filter New Signals').all()[index]?.json || {};
  const response = inputItem.json || {};
  const body = response.body || response;
  let text = '';
  if (Array.isArray(body.output)) {
    for (const block of body.output) {
      for (const content of (block.content || [])) {
        if (content.type === 'output_text') text += content.text || '';
      }
    }
  }
  text = text || body.output_text || body.text || '';
  let classification = null;
  let error = '';
  try {
    classification = typeof text === 'object' ? text : JSON.parse(String(text));
  } catch (parseError) {
    error = 'Invalid OpenAI JSON: ' + parseError.message;
  }
  const allowedCategory = ['performance','iterations','automation','hiring_signal','no_clear_pain'];
  const allowedStrength = ['high','medium','low'];
  if (classification && (typeof classification.is_relevant !== 'boolean' || !allowedCategory.includes(classification.pain_category) || !allowedStrength.includes(classification.evidence_strength))) {
    error = 'Malformed classification schema';
    classification = null;
  }
  if (!classification) {
    classification = { is_relevant: false, pain_category: 'no_clear_pain', pain_summary: '', pain_hypothesis: '', pain_signal: '', evidence_quote: '', evidence_strength: 'low', buyer_role: '', recommended_service: 'No recomendado', outreach_angle: '', reason: '', excluded_reason: error || 'No valid classification.' };
  }
  return { json: { ...source, classification, classification_valid: !error, item_errors: error ? [...(source.item_errors || []), error] : (source.item_errors || []) } };
});

const item = $input.first().json;
const c = item.classification || {};
const minQualifiedScore = Number(item.min_qualified_score || 65);
const priorityAScore = Number(item.priority_a_score || 80);
if (c.is_relevant !== true) {
  return [{ json: { ...item, score: 0, priority: 'C', next_action: 'Conservar como señal; no contactar' } }];
}
const haystack = `${item.source_title || ''} ${item.raw_text || ''} ${c.pain_signal || ''} ${c.pain_summary || ''}`.toLowerCase();
let score = 20;
if (c.evidence_strength === 'high') score += 30;
if (c.evidence_strength === 'medium') score += 15;
score += ({ performance: 25, iterations: 20, automation: 20, hiring_signal: 10, no_clear_pain: 0 }[c.pain_category] || 0);
if (/(rhino|grasshopper|computational design|parametric design|diseño computacional|diseño paramétrico)/i.test(haystack)) score += 10;
if (/(optimization|optimisation|simulation|facade|fachada|digital fabrication|additive manufacturing|generative design|fabricación digital)/i.test(haystack)) score += 10;
if (/(slow|crash|freeze|freezes|hours|heavy|large model|batch|multiple variants|automation|lento|bloquea|crashea|horas|pesad[ao]|variantes|automatización)/i.test(haystack)) score += 20;
score = Math.min(score, 100);
const priority = score >= priorityAScore ? 'A' : score >= minQualifiedScore ? 'B' : 'C';
const next_action = priority === 'A' ? 'Revisar empresa y localizar decisor en Sales Navigator en 24 horas' : priority === 'B' ? 'Validar decisor y evidencia antes de contactar' : 'Conservar como señal; no contactar';
return [{ json: { ...item, score, priority, next_action } }];

const stableId = (prefix, value, max = 24) => {
  const text = String(value || '').toLowerCase().trim();
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  const clean = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, max);
  const suffix = (hash >>> 0).toString(36);
  return prefix + '_' + (clean || 'item') + '_' + suffix;
};
return $input.all().map((item) => {
  const j = item.json;
  const c = j.classification || {};
  const now = new Date().toISOString();
  const companyId = stableId('co', j.domain || j.company_name, 28);
  return { json: { signal_id: stableId('sig', j.dedupe_key || j.source_url || j.company_name, 36), company_id: companyId, company_name: j.company_name, source_url: j.source_url, source_type: j.source_type, source_title: j.source_title, raw_text: j.raw_text, pain_category: c.pain_category || 'no_clear_pain', pain_signal: c.pain_signal || '', evidence_quote: c.evidence_quote || '', evidence_strength: c.evidence_strength || 'low', detected_at: j.detected_at, analyzed_at: now, status: c.is_relevant ? (j.score >= Number(j.min_qualified_score || 65) ? 'Cualificado' : 'Clasificado') : 'Descartado', dedupe_key: j.dedupe_key, run_id: j.run_id, score: j.score, priority: j.priority, next_action: j.next_action, website: j.website, domain: j.domain, country: j.country, classification: c, min_qualified_score: j.min_qualified_score } };
});

const now = new Date().toISOString();
return $input.all().map((item) => {
  const j = item.json;
  return { json: { company_id: j.company_id, company_name: j.company_name, website: j.website, domain: j.domain, linkedin_company_url: '', country: j.country, city: '', sector: '', company_size: '', source: j.source_type, first_seen_at: j.detected_at || now, last_seen_at: now, status: j.score >= Number(j.min_qualified_score || 65) ? 'Analizando' : 'Nuevo', notes: `Última señal: ${j.source_url}` } };
});

const stableId = (prefix, value, max = 24) => {
  const text = String(value || '').toLowerCase().trim();
  let hash = 2166136261;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  const clean = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, max);
  const suffix = (hash >>> 0).toString(36);
  return prefix + '_' + (clean || 'item') + '_' + suffix;
};
return $input.all()
  .filter((item) => Number(item.json.score || 0) >= Number(item.json.min_qualified_score || 65))
  .map((item) => {
    const j = item.json;
    const c = j.classification || {};
    const companyId = stableId('co', j.domain || j.company_name, 28);
    return { json: { lead_id: stableId('lead', companyId + '|' + (j.source_url || j.dedupe_key), 36), company_id: companyId, company_name: j.company_name, website: j.website, domain: j.domain, country: j.country, buyer_role: c.buyer_role || 'Responsable de diseño computacional / dirección técnica', pain_summary: c.pain_summary || '', pain_hypothesis: c.pain_hypothesis || '', recommended_service: c.recommended_service || 'No recomendado', outreach_angle: c.outreach_angle || '', score: j.score, priority: j.priority, next_action: j.next_action, lead_status: 'Nuevo', source_signal_id: stableId('sig', j.dedupe_key || j.source_url || j.company_name, 36), created_at: new Date().toISOString(), updated_at: new Date().toISOString(), decision_maker_name: '', decision_maker_role: '', decision_maker_linkedin_url: '', apollo_enriched_at: '', email: '', outreach_status: 'Pendiente' } };
  });

const j = $input.first().json;
const run = $('Initialize Run').first().json;
const errors = Array.isArray(j.item_errors) ? j.item_errors.join('; ') : '';
return [{ json: { run_id: run.run_id, workflow_name: run.workflow_name, started_at: run.started_at, finished_at: new Date().toISOString(), status: errors ? 'Completed with errors' : 'Completed', sources_requested: 1, raw_items: Number(j.raw_items || 0), new_signals: 0, qualified_leads: 0, errors, details: 'Source ' + (j.source_id || '') + ' did not produce usable Maps results. Status: ' + (j.apify_status || 'unknown') } }];

const item = $input.first().json;
const tokenEnvVar = item.apify_token_env_var || item.default_apify_token_env_var || 'APIFY_TOKEN';
const token = $env[tokenEnvVar] || $env.APIFY_TOKEN || '';
const errors = Array.isArray(item.item_errors) ? item.item_errors.slice() : [];
const endpoint = String(item.endpoint_url || '').trim();
if (!endpoint) errors.push('Missing Apify endpoint_url for ' + (item.source_id || 'source'));
if (!token) errors.push('Missing Apify token environment variable: ' + tokenEnvVar);
const input = {
  includeWebResults: false,
  language: item.apify_input?.language || 'en',
  locationQuery: item.apify_input?.locationQuery || item.country || '',
  maxCrawledPlacesPerSearch: Math.max(1, Math.min(Number(item.apify_input?.maxCrawledPlacesPerSearch || item.max_items_per_query || 20), 100)),
  maxImages: 0,
  maximumLeadsEnrichmentRecords: 0,
  scrapeContacts: false,
  scrapeDirectories: false,
  scrapeImageAuthors: false,
  scrapePlaceDetailPage: false,
  scrapeReviewsPersonalData: false,
  searchStringsArray: item.apify_input?.searchStringsArray || [item.query].filter(Boolean),
  skipClosedPlaces: true,
};
return [{
  json: {
    ...item,
    item_errors: errors,
    apify_token: token,
    apify_input: input,
    apify_start_url: token ? endpoint + token : endpoint,
    apify_status: errors.length ? 'CONFIG_ERROR' : 'READY'
  }
}];
